<?php use App\Core\Csrf; use App\Helpers\ViewHelper; $button = 'inline-flex min-h-10 items-center justify-center gap-2 rounded-xl px-3.5 py-2 text-xs font-semibold transition focus-visible:outline-none focus-visible:ring-4 focus-visible:ring-blue-100'; $field = 'block min-h-10 w-full rounded-xl border border-slate-300 bg-white px-3 py-2 text-sm text-slate-900 outline-none focus:border-blue-700 focus:ring-4 focus:ring-blue-100'; ?>
<div class="space-y-6"><header><p class="text-[11px] font-bold uppercase tracking-[0.18em] text-orange-600">Khuyến mại</p><h2 class="mt-2 text-2xl font-bold tracking-tight text-slate-950 sm:text-3xl">Mã giảm giá</h2><p class="mt-2 text-sm text-slate-500">Tạo và quản lý các chương trình ưu đãi cho khách hàng.</p></header><?php if (!empty($error)): ?><div role="alert" class="flex items-start gap-3 rounded-xl border border-red-200 bg-red-50 px-4 py-3.5 text-sm text-red-800"><span class="material-symbols-outlined" aria-hidden="true">error</span><?= ViewHelper::escape($error) ?></div><?php endif; ?><form class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm sm:p-6" method="post" action="/admin/vouchers"><?= Csrf::field() ?><div class="mb-5 flex items-center gap-3"><span class="flex size-10 items-center justify-center rounded-xl bg-orange-50 text-orange-700"><span class="material-symbols-outlined" aria-hidden="true">sell</span></span><h3 class="text-lg font-bold text-slate-950">Tạo voucher mới</h3></div><div class="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><label class="text-sm font-semibold text-slate-800">Mã voucher<input class="<?= $field ?> mt-2" name="code" placeholder="WELCOME10" required></label><label class="text-sm font-semibold text-slate-800">Loại<select class="<?= $field ?> mt-2" name="type"><option value="percent">Theo phần trăm</option><option value="fixed">Theo số tiền</option></select></label><label class="text-sm font-semibold text-slate-800">Giá trị<input class="<?= $field ?> mt-2" name="value" type="number" min="1" required></label><label class="text-sm font-semibold text-slate-800">Đơn tối thiểu<input class="<?= $field ?> mt-2" name="min_order_amount" type="number" min="0" value="0"></label><label class="text-sm font-semibold text-slate-800">Bắt đầu<input class="<?= $field ?> mt-2" name="starts_at" type="datetime-local"></label><label class="text-sm font-semibold text-slate-800">Kết thúc<input class="<?= $field ?> mt-2" name="expires_at" type="datetime-local"></label><label class="text-sm font-semibold text-slate-800">Giới hạn lượt dùng<input class="<?= $field ?> mt-2" name="usage_limit" type="number" min="1" placeholder="Không giới hạn"></label></div><button class="<?= $button ?> mt-5 bg-orange-700 text-white hover:bg-orange-800" type="submit"><span class="material-symbols-outlined text-[18px]" aria-hidden="true">add</span>Tạo voucher</button></form><div class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div class="overflow-x-auto"><table class="w-full min-w-[760px] border-collapse text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-[0.1em] text-slate-500"><tr><th class="px-4 py-4">Mã</th><th class="px-4 py-4">Loại</th><th class="px-4 py-4">Giá trị</th><th class="px-4 py-4">Hiệu lực</th><th class="px-4 py-4">Đã dùng</th><th class="px-4 py-4">Thao tác</th></tr></thead><tbody class="divide-y divide-slate-100"><?php foreach ($vouchers as $voucher): ?><tr class="text-slate-700"><td class="px-4 py-4 font-bold text-slate-900"><?= ViewHelper::escape($voucher['code']) ?></td><td class="px-4 py-4"><?= $voucher['type'] === 'percent' ? 'Phần trăm' : 'Số tiền' ?></td><td class="px-4 py-4 font-semibold text-orange-700"><?= (int)$voucher['value'] ?><?= $voucher['type'] === 'percent' ? '%' : ' đ' ?></td><td class="px-4 py-4 text-xs text-slate-500"><?= ViewHelper::escape((string)($voucher['expires_at'] ?: 'Không thời hạn')) ?></td><td class="px-4 py-4"><?= (int)$voucher['used_count'] ?><?= $voucher['usage_limit'] === null ? '' : ' / ' . (int)$voucher['usage_limit'] ?></td><td class="px-4 py-4"><form method="post" action="/admin/vouchers/<?= (int)$voucher['id'] ?>/delete"><?= Csrf::field() ?><button class="<?= $button ?> border border-red-200 bg-red-50 text-red-700 hover:bg-red-100" type="submit"><span class="material-symbols-outlined text-[16px]" aria-hidden="true">delete</span>Xóa</button></form></td></tr><?php endforeach; ?></tbody></table></div></div></div>